using System;using System.IO;using System.Linq;
namespace SargasPC {
 public class PcScanSettings {public string[] Roots;public bool AutomaticUpdates=true,DetectionControl;public bool PauseOnBattery=true,PauseWhenBusy=true,UseCleanCache=true;public int PeriodHours=24,StepDelaySeconds=5;}
 public static class PcScanPolicy {
  public static string[] DriveRoots(string[] roots){if(roots==null||roots.Length<1||roots.Length>16)throw new IOException("Pasirinkite nuo 1 iki 16 vietinių diskų.");var result=roots.Select(x=>x==null?"":x.ToUpperInvariant()).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(result.Any(x=>x.Length!=3||x[0]<'A'||x[0]>'Z'||x[1]!=':'||x[2]!='\\'))throw new IOException("Leidžiamos tik vietinių diskų šaknys, pavyzdžiui C:\\; tinklo keliai nepriimami.");return result;}
  public static void Validate(PcScanSettings cfg){if(cfg==null||cfg.PeriodHours<6||cfg.PeriodHours>168||cfg.StepDelaySeconds<1||cfg.StepDelaySeconds>30)throw new IOException("Grafikas: 6–168 val.; pauzė tarp aplankų: 1–30 s.");DriveRoots(cfg.Roots);}
  public static bool ReadyForScanCommand(ServiceHeartbeat hb,string[] roots,long began,long now){return ServiceHeartbeat.Fresh(hb,now)&&hb.At>=began&&hb.Version>=49&&hb.ManualControlReady&&hb.EngineReady&&hb.State!="STARTING"&&!hb.State.StartsWith("ERROR",StringComparison.Ordinal)&&!hb.State.StartsWith("STOPPED",StringComparison.Ordinal)&&hb.ScanRoots!=null&&hb.ScanRoots.SequenceEqual(roots,StringComparer.OrdinalIgnoreCase);}
  public static bool NewCycle(int pending,long finished){return pending==0&&finished>0;}
  public static string Summary(ServiceHeartbeat s){if(s==null)return "Diskų patikros eiga neperskaityta.";return "Diskų patikros šaknys: "+(s.ScanRoots==null?"senas signalas":string.Join(", ",s.ScanRoots))+"; aplankų lygių aplankyta: "+s.DirectoryChecks+"; eilėje: "+s.Pending+".\r\n"+(s.ScanFinished>0?"Ciklas baigtas; perskaitykite spragas ir radinius.":s.ScanStarted>0?"Ciklas pradėtas; eiga išsaugoma po aplanko ir tęsiama po perkrovimo.":"Ciklo pradžia nepatvirtinta.")+" Procentas neskaičiuojamas, nes visi poaplankiai dar gali būti neatrasti.\r\nFailų pokyčių įvykiai: "+(s.RealtimeReady?"stebimi pasirinktuose diskuose; failas tikrinamas po įrašymo":"aprėptis nepatvirtinta")+"; eilėje: "+s.RealtimePending+"; prarasti / atmesti: "+s.RealtimeDropped+"; nepatvirtinta: "+s.RealtimeUnverified+".\r\n"+(s.RealtimeBulkChangeAlert?"DĖMESIO: masinių failų pakeitimų audito signalas aktyvus (bent "+s.RealtimeBulkChangeDistinctPaths+" skirtingų kelių). Tai nepatvirtina kenkėjo; procesas nenustatytas ir failai neblokuojami.\r\n":"")+"Tai nėra failų vykdymo blokavimas; periodinis diskų ciklas veikia atskirai.";}
 }
}
